package com.vignesh.focuslist.ui.component

import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * The Upcoming mascot: the cat lying down, eyes open.
 *
 * Settled but awake, because nothing is coming yet and something eventually
 * will be. Between Inbox's sleep and Today's sitting up.
 *
 * Drawn from `cat-hd-empty-upcoming`. The seven poses share one scale factor
 * rather than a common width or height: a cat sitting is taller than the same
 * cat lying down, and normalising either dimension would have made it read as
 * two differently sized animals. [MascotImage] explains why the paths are built
 * in Kotlin and which colour role each tone takes.
 */
@Composable
internal fun UpcomingMascot(modifier: Modifier = Modifier) {
    MascotImage(
        width = MascotWidth,
        height = MascotHeight,
        modifier = modifier,
        build = ::catLying
    )
}

private const val MascotWidth = 253.76f
private const val MascotHeight = 132.34f

private fun catLying(light: Color, mid: Color, dark: Color): ImageVector =
    ImageVector.Builder(
        name = "UpcomingCatLying",
        defaultWidth = MascotWidth.dp,
        defaultHeight = MascotHeight.dp,
        viewportWidth = 976f,
        viewportHeight = 509f
    )
        .addPath(
            pathData = addPathNodes(GroundShadow),
            fill = SolidColor(light)
        )
        .addPath(
            pathData = addPathNodes(Body),
            fill = SolidColor(light)
        )
        .addPath(
            pathData = addPathNodes(Tail),
            fill = SolidColor(mid)
        )
        .addPath(
            pathData = addPathNodes(PawShading1),
            fill = SolidColor(mid)
        )
        .addPath(
            pathData = addPathNodes(PawShading2),
            fill = SolidColor(mid)
        )
        .addPath(
            pathData = addPathNodes(PawShading3),
            fill = SolidColor(mid)
        )
        .addPath(
            pathData = addPathNodes(Nose),
            fill = SolidColor(dark)
        )
        .addPath(
            pathData = addPathNodes(EyeLeft),
            fill = SolidColor(dark)
        )
        .addPath(
            pathData = addPathNodes(EyeRight),
            fill = SolidColor(dark)
        )
        .build()

